	function getActionSets() { var i = 1; var sets = [];  while (true) { 
	var ref = new ActionReference(); ref.putIndex(charIDToTypeID('ASet'), i); var desc; var lvl = $.level; $.level = 0; try { desc = executeActionGet(ref); } 
	catch (e) { break; } finally { $.level = lvl; } if (desc.hasKey(charIDToTypeID('Nm  '))) { var set = {}; set.index = i; set.name = desc.getString(charIDToTypeID('Nm  ')); 
	set.toString = function() { return this.name; }; set.count = desc.getInteger(charIDToTypeID('NmbC')); set.actions = []; for (var j = 1; j <= set.count; j++) { 
	var ref = new ActionReference(); ref.putIndex(charIDToTypeID('Actn'), j); ref.putIndex(charIDToTypeID('ASet'), set.index); var adesc = executeActionGet(ref); 
	var actName = adesc.getString(charIDToTypeID('Nm  ')); set.actions.push(actName); } sets.push(set); } i++; } return sets; 
}

function getActions(aset) { 
	try { var i = 1; var names = []; if (!aset) { throw 'Action set must be specified'; }}  catch (e) {ckA.value = false;  general.enabled=false;}
	while (true) { var ref = new ActionReference(); ref.putIndex(charIDToTypeID('ASet'), i);  var desc; try { desc = executeActionGet(ref); } catch (e) {break; }
	if (desc.hasKey(charIDToTypeID('Nm  '))) { var name = desc.getString(charIDToTypeID('Nm  ')); if (name == aset) { var count = desc.getInteger(charIDToTypeID('NmbC')); 
	var names = []; for (var j = 1; j <= count; j++) { var ref = new ActionReference(); ref.putIndex(charIDToTypeID('Actn'), j);
	ref.putIndex(charIDToTypeID('ASet'), i); var adesc = executeActionGet(ref); var actName = adesc.getString(charIDToTypeID('Nm  ')); 
	names.push(actName); } break; } } i++; } return names; 
}
