function RolandRun(){
    var exe_name = "Roland VersaWorks.exe"
    var tmp_name = "tmp.tmp"
    system("tasklist >%TEMP%/"+tmp_name)
    var file = new File(Folder.temp.fsName + "/" + tmp_name);
    file.open("r");var s = file.read();file.close();file.remove();
    if (s.search(new RegExp(exe_name, "i")) >= 0){}
    else{var f = File("C:/Program Files (x86)/Roland VersaWorks/VersaWorks/Roland VersaWorks.exe"); f.execute()}
}